'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');
const tick = () => new Promise(r => setImmediate(r));
function d() { let resolve, reject; const promise = new Promise((a, b) => { resolve = a; reject = b; }); return { promise, resolve, reject }; }

test('old flight completing does not detach newer flight', async () => {
  const gates = [d(), d()]; let calls = 0;
  const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
  const a = c.get('k'); await tick();
  c.invalidate('k');
  const b = c.get('k'); await tick();
  gates[0].resolve('old'); assert.equal(await a, 'old');
  const b2 = c.get('k');           // must join B, not start a third load
  gates[1].resolve('new');
  assert.equal(await b, 'new'); assert.equal(await b2, 'new');
  assert.equal(calls, 2); assert.equal(await c.get('k'), 'new'); assert.equal(calls, 2);
});

test('invalidate between load resolution and commit', async () => {
  let calls = 0;
  const c = createCache({ now: () => 0, load: () => (++calls === 1 ? 'stale' : 'fresh') });
  const a = c.get('k');
  await Promise.resolve(); await Promise.resolve();
  c.invalidate('k');
  assert.equal(await a, 'stale');
  assert.equal(await c.get('k'), 'fresh');
});

test('rejections are not cached; retry works; shared reason', async () => {
  let calls = 0; const reason = { not: 'error' };
  const c = createCache({ now: () => 0, load() { if (++calls === 1) throw reason; return 'ok'; } });
  const [x, y] = await Promise.allSettled([c.get('k'), c.get('k')]);
  assert.equal(x.reason, reason); assert.equal(y.reason, reason); assert.equal(calls, 1);
  assert.equal(await c.get('k'), 'ok'); assert.equal(c.size, 1);
});

test('detached rejecting flight does not drop newer flight', async () => {
  const gates = [d(), d()]; let calls = 0;
  const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
  const a = c.get('k'); await tick(); c.invalidate('k');
  const b = c.get('k'); await tick();
  gates[0].reject(new Error('x')); await assert.rejects(a);
  const b2 = c.get('k'); gates[1].resolve('v');
  assert.equal(await b2, 'v'); assert.equal(await b, 'v'); assert.equal(calls, 2);
});

test('set wins over pending load; TTL not restarted; expiry starts new load', async () => {
  let t = 0; const gates = [d(), d()]; let calls = 0;
  const c = createCache({ now: () => t, ttlMs: 10, load: () => gates[calls++].promise });
  const a = c.get('k'); await tick();
  c.set('k', 'manual');
  assert.equal(await c.get('k'), 'manual');
  t = 5; gates[0].resolve('loaded'); assert.equal(await a, 'loaded');
  assert.equal(await c.get('k'), 'manual');
  t = 10; assert.equal(c.size, 0);
  const b = c.get('k'); await tick(); assert.equal(calls, 2);
  gates[1].resolve('v2'); assert.equal(await b, 'v2');
});

test('load calling invalidate synchronously does not store', async () => {
  let calls = 0; let c;
  c = createCache({ now: () => 0, load(k) { calls++; if (calls === 1) c.invalidate(k); return 'v' + calls; } });
  assert.equal(await c.get('k'), 'v1');
  assert.equal(c.size, 0);
  assert.equal(await c.get('k'), 'v2'); assert.equal(c.size, 1);
});

test('load reading own key joins its flight', async () => {
  let calls = 0; let c; let inner;
  c = createCache({ now: () => 0, load(k) { calls++; inner = c.get(k); return 'v'; } });
  assert.equal(await c.get('k'), 'v'); assert.equal(await inner, 'v'); assert.equal(calls, 1);
});

test('clear detaches all flights; ttl 0 dedups but never reuses', async () => {
  const g = d(); let calls = 0;
  const c = createCache({ now: () => 0, ttlMs: 0, load: () => (++calls === 1 ? g.promise : 'n') });
  const a = c.get('k'), a2 = c.get('k'); await tick(); assert.equal(calls, 1);
  c.clear(); g.resolve('o');
  assert.equal(await a, 'o'); assert.equal(await a2, 'o');
  assert.equal(await c.get('k'), 'n'); assert.equal(await c.get('k'), 'n'); assert.equal(calls, 3);
});

content.text:
The race is fixed and `node --test` passes (1/1). The fix is a single change in `src/flight.js`.

**Root cause:** when a load finished, `flights.run` always removed the key's flight from the registry and stored the result. It never checked whether `invalidate`, `set` or `clear` had already detached that flight. Three bugs followed from this, which is why the problem looked intermittent:

1. **Old value comes back (the production bug).** A load that was detached could still store its value. That happened whenever the invalidation came while the load was pending, or after it had resolved but before its result was stored. With `set`, the old load could also overwrite the new value and restart its TTL.
2. **A newer load gets dropped.** When an old load finished, it removed whatever flight was registered for the key, even if that was the fresh one started after the invalidation. Readers then started a third load, which broke deduplication.
3. **Failures stay stuck.** A rejected load was never removed from the registry. Every later `get` got the same rejection and retries never happened, which breaks the rule that "rejected loads are never cached".

**Fix:** a finishing load now checks `pending.get(key) === promise`. Only the flight still registered for the key can store a value or remove itself. Rejections take the same check and then rethrow, so every waiter gets the same reason. A detached load still delivers its own value or rejection to its original readers. The rejection handling stays on the one shared promise chain, so it adds no unhandled-rejection noise.

`src/cache.js` and `src/clock.js` were already correct against the contract and are unchanged. The `createCache` export and API, deduplication and the injectable clock are as before; I added no timers or dependencies.

**Checks:** besides the existing test, I wrote 8 temporary tests and they all passed against the fix. I didn't run them against the old code. They covered:
- an old load finishing after an invalidate without dropping the newer load (both for success and for rejection);
- an invalidate landing between the load resolving and its value being stored;
- rejections, including non-Error reasons, reaching all waiters with the same reason, and a retry succeeding afterwards;
- `set` winning over a pending load without its TTL being restarted, and a new load starting once it expires;
- a load calling `invalidate` on its own key, and a load reading its own key and joining its flight;
- `clear` detaching flights, and `ttlMs = 0` still deduplicating but never reusing a value.

I deleted those tests afterwards because `test/` can't be modified. Only the original single-ordering test remains, so these cases are no longer covered by the suite.
